 function t(language){return copy[language==='ms'?'ms':'en'];}
 function action(label,name,extra='',primary=false){return '<button type="button" class="analytics-btn'+(primary?' primary':'')+'" data-analytics-action="'+name+'" '+extra+'>'+esc(label)+'</button>';}
 function evidence(row,c){return n(row.answered)===0?c.notAssessed:n(row.distinctAnswered)<3?c.few:c.progress;}
 function graph(row,c){
  const answered=n(row.answered),value=answered?Math.min(100,Math.round(n(row.independentFirstTry)/answered*100)):0,label=answered?n(row.independentFirstTry)+' / '+answered:c.notAssessed;
  return '<div class="analytics-bar" role="meter" aria-label="'+esc(c.independent)+'" aria-valuemin="0" aria-valuemax="'+Math.max(1,answered)+'" aria-valuenow="'+Math.min(answered,n(row.independentFirstTry))+'" aria-valuetext="'+esc(label)+'"><span style="width:'+value+'%"></span></div><span class="analytics-bar-value">'+esc(label)+'</span>';
 }
