  const sharing='<div data-analytics-sync>'+syncHTML(status,language)+'</div><details class="analytics-disclosure analytics-backup" data-report-disclosure="backup"><summary>'+c.backup+'</summary><p class="analytics-note">'+c.backupNote+'</p><div class="analytics-actions">'+action(c.json,'export','data-exportformat="json"')+'</div></details>';
  return '<article class="learning-report" lang="'+(language==='ms'?'ms':'en')+'" data-view="'+view+'"><div class="analytics-report-head"><p class="analytics-intro">'+c.intro+'</p><label class="analytics-source">'+c.scope+'<select data-analytics-scope>'+['all','gameplay','practice','review'].map(s=>'<option value="'+s+'"'+(scope===s?' selected':'')+'>'+c[s]+'</option>').join('')+'</select></label></div><nav class="analytics-nav" aria-label="'+c.nav+'">'+views.map(name=>action(c[name],'view','data-view="'+name+'" aria-pressed="'+(view===name)+'" aria-controls="analytics-view-'+name+'"'+(view===name?' autofocus':''))).join('')+'</nav>'+(scope==='review'?'<p class="analytics-scope-note">'+c.reviewNote+'</p>':'')+(status.state==='save-error'?'<div class="analytics-storage-attention" role="alert"><p>'+c.attention+'</p>'+action(c.openSharing,'view','data-view="sharing"')+'</div>':'')+panel('overview',overview).replace('data-analytics-panel="overview"','id="analytics-view-overview" data-analytics-panel="overview"')+panel('details',details).replace('data-analytics-panel="details"','id="analytics-view-details" data-analytics-panel="details"')+panel('sharing',sharing).replace('data-analytics-panel="sharing"','id="analytics-view-sharing" data-analytics-panel="sharing"')+'<p class="analytics-disclaimer">'+c.diagnostic+'</p></article>';
